#!/usr/bin/env bash
# typecheck:infra — tsc over the two SST configs, which sit outside the pnpm
# workspace so `turbo run typecheck` never visits them.
#
# Both files open with `/// <reference path="./.sst/platform/config.d.ts" />`,
# and that file is generated by `sst install`, not built. Without it tsc reports
# hundreds of "Cannot find name 'aws'" errors that hide the real cause, so check
# for it first and say how to create it. Bootstrap steps: docs/agents/local-dev.md.
set -euo pipefail

cd "$(dirname "$0")/.."

missing=()
[[ -f .sst/platform/config.d.ts ]] || missing+=(".sst/platform")
[[ -f infra/.sst/platform/config.d.ts ]] || missing+=("infra/.sst/platform")

if (( ${#missing[@]} > 0 )); then
  echo "typecheck:infra needs generated SST platform types that are missing: ${missing[*]}" >&2
  echo "Generate them (details in docs/agents/local-dev.md):" >&2
  echo "  node_modules/.bin/sst install" >&2
  echo "  (cd infra && ../node_modules/.bin/sst install --config selfhost.config.ts --stage production)" >&2
  exit 1
fi

exec node_modules/.bin/tsc --noEmit --strict --skipLibCheck \
  --target ES2022 --module ESNext --moduleResolution bundler \
  --resolveJsonModule --esModuleInterop --allowSyntheticDefaultImports \
  sst.config.ts infra/selfhost.config.ts
